import { useMemo, useState } from 'react';
import {
  JxCard,
  JxChip,
  JxChipGroup,
  JxStack,
  JxInline,
  JxText,
  JxHeading,
  JxDivider,
  JxCircularProgress,
  JxBadge,
  JxEmptyState,
  JxButton,
  JxPagination,
} from '@jinx-ui/react';

type ProjectStatus = 'active' | 'warning' | 'exceeded' | 'closed';

interface ProjectBudget {
  id: string;
  name: string;
  quotaPercent: number;
  status: ProjectStatus;
}

const PROJECTS: ProjectBudget[] = [
  { id: 'p1', name: 'Атлас CRM', quotaPercent: 42, status: 'active' },
  { id: 'p2', name: 'Портал закупок', quotaPercent: 78, status: 'warning' },
  { id: 'p3', name: 'Мобильный банк', quotaPercent: 104, status: 'exceeded' },
  { id: 'p4', name: 'Аналитика продаж', quotaPercent: 15, status: 'active' },
  { id: 'p5', name: 'HR-платформа', quotaPercent: 91, status: 'warning' },
  { id: 'p6', name: 'Логистика Юг', quotaPercent: 60, status: 'active' },
  { id: 'p7', name: 'Старый биллинг', quotaPercent: 100, status: 'closed' },
  { id: 'p8', name: 'Складской учёт', quotaPercent: 33, status: 'active' },
  { id: 'p9', name: 'Кабинет партнёра', quotaPercent: 87, status: 'warning' },
  { id: 'p10', name: 'Служба поддержки', quotaPercent: 120, status: 'exceeded' },
  { id: 'p11', name: 'Архив документов', quotaPercent: 100, status: 'closed' },
  { id: 'p12', name: 'Онбординг клиентов', quotaPercent: 55, status: 'active' },
];

const STATUS_LABEL: Record<ProjectStatus, string> = {
  active: 'В норме',
  warning: 'Близко к лимиту',
  exceeded: 'Превышено',
  closed: 'Закрыт',
};

const STATUS_TONE: Record<ProjectStatus, 'success' | 'warning' | 'danger' | 'neutral'> = {
  active: 'success',
  warning: 'warning',
  exceeded: 'danger',
  closed: 'neutral',
};

const ALL_STATUSES: ProjectStatus[] = ['active', 'warning', 'exceeded', 'closed'];

const PAGE_SIZE = 5;

export default function ProjectBudgetPanel() {
  const [activeStatuses, setActiveStatuses] = useState<ProjectStatus[]>(ALL_STATUSES);
  const [page, setPage] = useState(1);

  const filteredProjects = useMemo(
    () => PROJECTS.filter((project) => activeStatuses.includes(project.status)),
    [activeStatuses],
  );

  const totalPages = Math.max(1, Math.ceil(filteredProjects.length / PAGE_SIZE));
  const currentPage = Math.min(page, totalPages);

  const pagedProjects = filteredProjects.slice(
    (currentPage - 1) * PAGE_SIZE,
    currentPage * PAGE_SIZE,
  );

  const toggleStatus = (status: ProjectStatus) => {
    setActiveStatuses((prev) =>
      prev.includes(status) ? prev.filter((s) => s !== status) : [...prev, status],
    );
    setPage(1);
  };

  const resetFilters = () => {
    setActiveStatuses(ALL_STATUSES);
    setPage(1);
  };

  return (
    <JxCard className="jx-p-lg" style={{ maxWidth: 640 }}>
      <JxStack gap="md">
        <JxStack gap="xs">
          <JxHeading level={3}>Расход по проектам</JxHeading>
          <JxText tone="muted" size="sm">
            Фильтр по статусу расходования квоты
          </JxText>
        </JxStack>

        <JxChipGroup wrap>
          {ALL_STATUSES.map((status) => (
            <JxChip
              key={status}
              tone={STATUS_TONE[status]}
              selected={activeStatuses.includes(status)}
              removable={activeStatuses.includes(status)}
              onRemove={() => toggleStatus(status)}
              onClick={() => toggleStatus(status)}
            >
              {STATUS_LABEL[status]}
            </JxChip>
          ))}
        </JxChipGroup>

        <JxDivider />

        {filteredProjects.length === 0 ? (
          <JxEmptyState
            title="Ничего не найдено"
            description="Нет проектов, подходящих под выбранные фильтры статуса."
          >
            <JxButton variant="secondary" onClick={resetFilters}>
              Сбросить фильтры
            </JxButton>
          </JxEmptyState>
        ) : (
          <JxStack gap="sm">
            {pagedProjects.map((project) => (
              <JxInline
                key={project.id}
                align="center"
                justify="space-between"
                gap="md"
                className="jx-p-sm jx-rounded jx-bg-surface-subtle"
              >
                <JxInline align="center" gap="sm">
                  <JxCircularProgress
                    value={Math.min(project.quotaPercent, 100)}
                    size="sm"
                    tone={STATUS_TONE[project.status]}
                    label={`${project.quotaPercent}%`}
                  />
                  <JxText weight="medium">{project.name}</JxText>
                </JxInline>

                <JxBadge tone={STATUS_TONE[project.status]}>
                  {STATUS_LABEL[project.status]}
                </JxBadge>
              </JxInline>
            ))}

            <JxInline justify="center" className="jx-pt-sm">
              <JxPagination
                page={currentPage}
                pageCount={totalPages}
                onPageChange={setPage}
              />
            </JxInline>
          </JxStack>
        )}
      </JxStack>
    </JxCard>
  );
}

